def change_base(x: int, base: int) -> str:
    """Change numerical base of input number x to base (which must be < 10)."""
    if base < 2 or base > 9:
        raise ValueError("Base must be between 2 and 9 inclusive.")
    if x == 0:
        return "0"
    digits = "0123456789"
    chars = []
    n = abs(x)
    while n > 0:
        rem = n % base
        chars.append(digits[rem])
        n //= base
    # If x was negative, add a minus sign
    if x < 0:
        chars.insert(0, '-')
    return ''.join(reversed(chars))
