import math

def is_multiply_prime(a: int) -> bool:
    """
    Returns True if the given number a (less than 100) is the product of exactly three prime numbers,
    otherwise returns False.
    """
    if a < 2:
        return False

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.isqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Collect all prime factors with multiplicity
    factors = []
    n = a
    temp = n
    # Count multiplicity
    p = 2
    while p * p <= temp:
        while temp % p == 0 and is_prime(p):
            factors.append(p)
            temp //= p
        p += 1 if p == 2 else 2  # after 2, check only odd numbers
    if temp > 1 and is_prime(temp):
        factors.append(temp)

    # Need exactly 3 prime factors (with multiplicity) and all must be prime
    if len(factors) != 3:
        return False
    # (Since the algorithm above collects primes with multiplicity, this is enough)
    return True
