def numerical_letter_grade(grades):
    """
    Translates a list of numeric grades (on a 4.0 scale) into letter grades
    based on the provided grading table.

    Parameters:
    grades (list of float/int): List of GPA values (0.0 to 4.0 inclusive)

    Returns:
    list of str: Corresponding letter grades
    """
    import math

    def get_letter(g):
        if g >= 4.0:
            return 'A+'
        elif g >= 3.7:
            return 'A'
        elif g >= 3.3:
            return 'A-'
        elif g >= 3.0:
            return 'B+'
        elif g >= 2.7:
            return 'B'
        elif g >= 2.3:
            return 'B-'
        elif g >= 2.0:
            return 'C+'
        elif g >= 1.7:
            return 'C'
        elif g >= 1.3:
            return 'C-'
        elif g >= 1.0:
            return 'D+'
        elif g >= 0.7:
            return 'D'
        elif g >= 0.0:
            return 'D-'
        else:  # g < 0.0 (though not expected)
            return 'E'

    return [get_letter(g) for g in grades]

