import math

def count_up_to(n):
    """
    Returns a list of all prime numbers less than n.
    """
    if n <= 2:
        return []
    sieve = [True] * n
    sieve[0:2] = [False, False]  # 0 and 1 are not primes
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]
