import math

def closest_integer(value):
    """
    Takes a string representing a number and returns the closest integer.
    If equidistant between two integers, rounds away from zero.
    """
    # Convert the string to a float
    num = float(value)

    # Get the fractional part
    frac = num - math.floor(num)

    # If the fractional part is exactly 0.5 (or -0.5), round away from zero
    if abs(frac - 0.5) < 1e-9:  # Handles cases like 14.5, -14.5
        if frac > 0:
            return math.ceil(num)
        else:
            return math.floor(num)
    # Otherwise, standard rounding: if frac < 0.5, floor; else, ceil
    if frac < 0.5:
        return math.floor(num)
    else:
        return math.ceil(num)

