import re

def compare_one(a, b):
    """
    Takes two arguments which can be int, float, or string representations of numbers.
    Returns the larger value in its original type. Returns None if they are equal.
    String numbers like "2,3" are interpreted as floats.
    """
    def to_num(x):
        # Try to convert to float, handling commas as thousand separators
        if isinstance(x, (int, float)):
            return float(x)
        # For strings, try to parse with comma as decimal separator
        try:
            return float(re.sub(r'[.,]', '', x))
        except ValueError:
            # If can't parse, treat as string (for type comparison if needed)
            return x

    num_a = to_num(a)
    num_b = to_num(b)

    # Compare by numeric value
    if num_a > num_b:
        # Return original type of a
        if isinstance(a, (int, float)):
            return a
        else:
            # If a is a string, return it as-is
            return a
    elif num_b > num_a:
        # Return original type of b
        if isinstance(b, (int, float)):
            return b
        else:
            return b
    else:
        # Equal numeric value
